From e538ad9a1d79621f4a28a8ab24e5f85dad06e12c Mon Sep 17 00:00:00 2001
From: Peter Jones <pjones@redhat.com>
Date: Mon, 15 Feb 2016 13:27:41 -0500
Subject: [PATCH] Make guids be in correct byte order both in text and ram...

This is all because the EFI spec defines:

typedef struct {
	UINT32 Data1;
	UINT16 Data2;
	UINT16 Data3;
	UINT8
	Data4[8];
} EFI_GUID;

	{0x8BE4DF61,0x93CA,0x11d2,\
		{0xAA,0x0D,0x00,0xE0,0x98,0x03,0x2B,0x8C}}

but prints:
8BE4DF61-93CA-11d2-AA0D-00E098032B8C

But we decided to be "smart" and did:

typedef struct {
	uint32_t        a;
	uint16_t        b;
	uint16_t        c;
	uint16_t        d;
	uint8_t         e[6];
} efi_guid_t;

Which means d is effectively in big endian while a, b, and c are little
endian.  This is awful.

We also have efi_guid_t in the public header, so things can take
sizeof() on it, which seems ill advised in hindsight.

Thankfully, we also have the EFI_GUID() macro, which was getting things
right, so if things memcmp()'d or efi_guid_cmp()'d on that, it'd get it
right, and efibootmgr is, in fact, using that (via EFI_GUID_GLOBAL)
instead.

So now, keep them all in memory as le32-le16-le16-be16-b-b-b-b-b-b at
all times.  The only programs that should break were ther ones that were
already broken, and they'll need a rebuild.

Also fix a bug introduced in c0a2b3db1088af888d98c2223a648bc6f6274eea
which introduced at "1" into some definitions of efi_guid_empty.

(yes, it really says "d2" not "D2")

Signed-off-by: Peter Jones <pjones@redhat.com>

diff --git a/src/guid.c b/src/guid.c
index f438917..1c16d42 100644
--- a/src/guid.c
+++ b/src/guid.c
@@ -43,17 +43,26 @@ efi_guid_to_str(const efi_guid_t *guid, char **sp)

 	if (!sp) {
 		return snprintf(NULL, 0, GUID_FORMAT,
-				guid->a, guid->b, guid->c, bswap_16(guid->d),
+				le32_to_cpu(guid->a),
+				le16_to_cpu(guid->b),
+				le16_to_cpu(guid->c),
+				be16_to_cpu(guid->d),
 				guid->e[0], guid->e[1], guid->e[2], guid->e[3],
 				guid->e[4], guid->e[5]);
 	} else if (sp && *sp) {
 		return snprintf(*sp, GUID_LENGTH_WITH_NUL, GUID_FORMAT,
-				guid->a, guid->b, guid->c, bswap_16(guid->d),
+				le32_to_cpu(guid->a),
+				le16_to_cpu(guid->b),
+				le16_to_cpu(guid->c),
+				be16_to_cpu(guid->d),
 				guid->e[0], guid->e[1], guid->e[2], guid->e[3],
 				guid->e[4], guid->e[5]);
 	} else {
 		rc = asprintf(&ret, GUID_FORMAT,
-				guid->a, guid->b, guid->c, bswap_16(guid->d),
+				le32_to_cpu(guid->a),
+				le16_to_cpu(guid->b),
+				le16_to_cpu(guid->c),
+				be16_to_cpu(guid->d),
 				guid->e[0], guid->e[1], guid->e[2], guid->e[3],
 				guid->e[4], guid->e[5]);
 		if (rc >= 0)
@@ -172,17 +181,26 @@ efi_guid_to_id_guid(const efi_guid_t *guid, char **sp)
 	}
 	if (!sp) {
 		return snprintf(NULL, 0, "{"GUID_FORMAT"}",
-				guid->a, guid->b, guid->c, bswap_16(guid->d),
+				le32_to_cpu(guid->a),
+				le16_to_cpu(guid->b),
+				le16_to_cpu(guid->c),
+				be16_to_cpu(guid->d),
 				guid->e[0], guid->e[1], guid->e[2], guid->e[3],
 				guid->e[4], guid->e[5]);
 	} else if (sp && *sp) {
 		return snprintf(*sp, GUID_LENGTH_WITH_NUL+2, "{"GUID_FORMAT"}",
-				guid->a, guid->b, guid->c, bswap_16(guid->d),
+				le32_to_cpu(guid->a),
+				le16_to_cpu(guid->b),
+				le16_to_cpu(guid->c),
+				be16_to_cpu(guid->d),
 				guid->e[0], guid->e[1], guid->e[2], guid->e[3],
 				guid->e[4], guid->e[5]);
 	}
 	rc = asprintf(&ret, "{"GUID_FORMAT"}",
-			guid->a, guid->b, guid->c, bswap_16(guid->d),
+				le32_to_cpu(guid->a),
+				le16_to_cpu(guid->b),
+				le16_to_cpu(guid->c),
+				be16_to_cpu(guid->d),
 			guid->e[0], guid->e[1], guid->e[2], guid->e[3],
 			guid->e[4], guid->e[5]);
 	if (rc >= 0)

diff --git a/src/makeguids.c b/src/makeguids.c
index 254b9c0..65a68d6 100644
--- a/src/makeguids.c
+++ b/src/makeguids.c
@@ -147,7 +147,21 @@ main(int argc, char *argv[])

 	fprintf(header, "#ifndef EFIVAR_GUIDS_H\n#define EFIVAR_GUIDS_H 1\n\n");

-	fprintf(symout, "#include <efivar.h>\n\n");
+	fprintf(symout, "#include <efivar.h>\n");
+	fprintf(symout, "#include <endian.h>\n");
+	fprintf(symout, """\n\
+#if BYTE_ORDER == BIG_ENDIAN\n\
+#define cpu_to_be32(n) (n)\n\
+#define cpu_to_be16(n) (n)\n\
+#define cpu_to_le32(n) (__bswap_constant_32(n))\n\
+#define cpu_to_le16(n) (__bswap_constant_16(n))\n\
+#else\n\
+#define cpu_to_le32(n) (n)\n\
+#define cpu_to_le16(n) (n)\n\
+#define cpu_to_be32(n) (__bswap_constant_32(n))\n\
+#define cpu_to_be16(n) (__bswap_constant_16(n))\n\
+#endif\n\
+""");

 	for (unsigned int i = 0; i < line-1; i++) {
 		uint8_t *guid_data = (uint8_t *) &outbuf[i].guid;
@@ -158,7 +172,7 @@ main(int argc, char *argv[])
 		if (!strcmp(outbuf[i].symbol, "efi_guid_zero")) {
 			fprintf(symout, "const efi_guid_t\n"
 				"__attribute__((__visibility__ (\"default\")))\n"
-				"efi_guid_empty = {0x1,0x0,0x0,0x0,{0x0,0x0,0x0,0x0,0x0,0x0}};\n\n");
+				"efi_guid_empty = {0x0,0x0,0x0,0x0,{0x0,0x0,0x0,0x0,0x0,0x0}};\n\n");
 		}
 		if (!strcmp(outbuf[i].symbol, "efi_guid_zero")) {
 			fprintf(header, "extern const efi_guid_t efi_guid_empty __attribute__((__visibility__ (\"default\")));\n");
@@ -168,7 +182,7 @@ main(int argc, char *argv[])

 		fprintf(symout, "const \n"
 			"__attribute__((__visibility__ (\"default\")))\n"
-			"efi_guid_t %s = {0x%02x%02x%02x%02x,0x%02x%02x,0x%02x%02x,0x%02x%02x,{0x%02x,0x%02x,0x%02x,0x%02x,0x%02x,0x%02x}};\n\n",
+			"efi_guid_t %s = {cpu_to_le32(0x%02x%02x%02x%02x),cpu_to_le16(0x%02x%02x),cpu_to_le16(0x%02x%02x),cpu_to_be16(0x%02x%02x),{0x%02x,0x%02x,0x%02x,0x%02x,0x%02x,0x%02x}};\n\n",
 			outbuf[i].symbol,
 			guid_data[3], guid_data[2],
 			  guid_data[1], guid_data[0],
-- 
